<script setup lang="ts">
import { ArrowLeft, Connection, Delete, Edit, Plus, Refresh } from '@element-plus/icons-vue'

const props = withDefaults(defineProps<{
  centerTitle: string
  record: Record<string, any> | null
  loading?: boolean
  error?: string
  canManage?: boolean
  showPrice?: boolean
}>(), { loading: false, error: '', canManage: false, showPrice: false })

const emit = defineEmits<{ back: []; edit: []; delete: []; relate: []; editBom: []; retry: []; openRelation: [relation: any] }>()
const statusLabel = (value?: string) => ({ SUPPORTED: '正式支持', ON_SALE: '在售', OFF_SALE: '停售', ACTIVE: '启用', PUBLISHED: '已发布', DRAFT: '草稿', BETA: 'Beta', DISABLED: '停用', PLANNING: '规划中' } as Record<string, string>)[value || ''] || '状态待确认'
const metaLabel = (relation:any) => typeof relation.meta === 'string' ? relation.meta : Object.values(relation.meta || {}).filter(Boolean).join(' · ') || relation.summary || '查看关联详情'
</script>

<template>
  <section class="detail-page" v-loading="loading">
    <div class="detail-nav"><el-button link :icon="ArrowLeft" @click="emit('back')">返回{{ centerTitle }}</el-button></div>
    <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon><template #default><el-button :icon="Refresh" @click="emit('retry')">重新加载</el-button></template></el-alert>
    <template v-else-if="record">
      <header class="detail-hero-v3">
        <div class="record-symbol">{{ record.name?.slice(0, 1) }}</div>
        <div class="hero-copy"><div class="eyebrow">{{ centerTitle }} · 知识详情</div><h1>{{ record.name }}</h1><p>{{ record.summary || '暂无简介' }}</p><div class="hero-tags"><el-tag effect="plain">{{ statusLabel(record.status) }}</el-tag><el-tag v-if="record.modelCode" effect="plain">{{ record.modelCode }}</el-tag><el-tag v-if="record.version" effect="plain">版本 {{ record.version }}</el-tag><el-tag v-if="record.category" effect="plain">{{ record.category }}</el-tag></div></div>
        <div v-if="canManage" class="hero-actions"><el-button :icon="Edit" @click="emit('edit')">编辑</el-button><el-button type="danger" plain :icon="Delete" @click="emit('delete')">删除</el-button></div>
      </header>

      <div class="detail-layout">
        <main class="detail-main">
          <section class="detail-section"><div class="section-head"><div><h2>基础信息</h2><p>当前知识条目的核心属性与维护状态。</p></div></div><el-descriptions :column="2" border><el-descriptions-item label="名称">{{ record.name }}</el-descriptions-item><el-descriptions-item label="状态">{{ statusLabel(record.status) }}</el-descriptions-item><el-descriptions-item v-if="record.code" label="编码">{{ record.code }}</el-descriptions-item><el-descriptions-item v-if="record.modelCode" label="主型号">{{ record.modelCode }}</el-descriptions-item><el-descriptions-item v-if="record.version" label="版本">{{ record.version }}</el-descriptions-item><el-descriptions-item v-if="record.category" label="分类">{{ record.category }}</el-descriptions-item><el-descriptions-item v-if="record.softwareType" label="软件类型">{{ ({PLATFORM:'平台软件',CLIENT:'客户端软件',SERVICE:'服务组件'} as any)[record.softwareType] || record.softwareType }}</el-descriptions-item><el-descriptions-item v-if="record.vendor" label="厂商">{{ record.vendor }}</el-descriptions-item><el-descriptions-item v-if="record.deploymentMode" label="部署方式">{{ ({PRIVATE:'私有化部署',CLOUD:'云端部署',HYBRID:'混合部署'} as any)[record.deploymentMode] || record.deploymentMode }}</el-descriptions-item><el-descriptions-item v-if="record.supportedOs?.length" label="支持操作系统">{{ record.supportedOs.join('、') }}</el-descriptions-item><el-descriptions-item v-if="record.scene" label="适用场景">{{ record.scene }}</el-descriptions-item><el-descriptions-item v-if="record.tier" label="方案等级">{{ record.tier }}</el-descriptions-item><el-descriptions-item label="最近更新">{{ record.updatedAt ? new Date(record.updatedAt).toLocaleString() : '-' }}</el-descriptions-item></el-descriptions></section>

          <section v-if="record.painPoints" class="detail-section"><div class="section-head"><div><h2>业务痛点</h2><p>该场景重点解决的问题。</p></div></div><p class="long-copy">{{ record.painPoints }}</p></section>

          <section v-if="record.goals?.length || record.businessProcess?.length || record.coreCapabilitySummary" class="detail-section"><div class="section-head"><div><h2>建设目标与业务流程</h2><p>从问题到落地能力的场景建设路径。</p></div></div><div class="scene-columns"><div v-if="record.goals?.length"><h3>建设目标</h3><ol><li v-for="item in record.goals" :key="item">{{ item }}</li></ol></div><div v-if="record.businessProcess?.length"><h3>业务流程</h3><ol><li v-for="item in record.businessProcess" :key="item">{{ item }}</li></ol></div></div><el-alert v-if="record.coreCapabilitySummary" :title="record.coreCapabilitySummary" type="info" :closable="false" show-icon /></section>

          <section v-if="record.inputSummary || record.outputSummary" class="detail-section"><div class="section-head"><div><h2>输入与输出</h2><p>算法处理的数据范围与结果摘要。</p></div></div><el-descriptions :column="1" border><el-descriptions-item v-if="record.inputSummary" label="算法输入">{{ record.inputSummary }}</el-descriptions-item><el-descriptions-item v-if="record.outputSummary" label="算法输出">{{ record.outputSummary }}</el-descriptions-item></el-descriptions></section>

          <section v-if="record.functionType || Object.keys(record.inputRequirements||{}).length || Object.keys(record.deploymentRequirements||{}).length" class="detail-section"><div class="section-head"><div><h2>模型要求</h2><p>功能定位、输入约束与部署资源要求。</p></div></div><el-descriptions :column="2" border><el-descriptions-item v-if="record.functionType" label="功能类型">{{ record.functionType }}</el-descriptions-item><el-descriptions-item v-for="(value,key) in record.inputRequirements" :key="'input-'+key" :label="'输入 · '+key">{{ value }}</el-descriptions-item><el-descriptions-item v-for="(value,key) in record.deploymentRequirements" :key="'deploy-'+key" :label="'部署 · '+key">{{ value }}</el-descriptions-item></el-descriptions></section>

          <section v-if="Object.keys(record.metrics||{}).length || record.boundaries?.length" class="detail-section"><div class="section-head"><div><h2>核心指标与适用边界</h2><p>关键性能数据和限制条件。</p></div></div><div v-if="Object.keys(record.metrics||{}).length" class="metric-list"><div v-for="(value,key) in record.metrics" :key="key"><span>{{ key }}</span><strong>{{ value }}</strong></div></div><ul v-if="record.boundaries?.length" class="boundary-list"><li v-for="item in record.boundaries" :key="item">{{ item }}</li></ul></section>

          <section v-if="record.targetDescription || record.coverageScope || record.architectureSummary || record.implementationNotes" class="detail-section"><div class="section-head"><div><h2>方案设计</h2><p>目标、覆盖范围、架构与实施说明。</p></div></div><el-descriptions :column="1" border><el-descriptions-item v-if="record.targetDescription" label="方案目标">{{ record.targetDescription }}</el-descriptions-item><el-descriptions-item v-if="record.coverageScope" label="覆盖范围">{{ record.coverageScope }}</el-descriptions-item><el-descriptions-item v-if="record.architectureSummary" label="方案架构">{{ record.architectureSummary }}</el-descriptions-item><el-descriptions-item v-if="record.implementationNotes" label="实施说明">{{ record.implementationNotes }}</el-descriptions-item></el-descriptions></section>

          <section class="detail-section"><div class="section-head"><div><h2>关联知识</h2><p>复用已有知识对象，支持双向追溯。</p></div><el-button v-if="canManage" :icon="Plus" @click="emit('relate')">选择关联</el-button></div><div v-if="record.relations?.length" class="relation-list"><button v-for="relation in record.relations" :key="relation.type + relation.id" type="button" @click="emit('openRelation', relation)"><span class="relation-icon"><el-icon><Connection /></el-icon></span><span><strong>{{ relation.name }}</strong><small>{{ metaLabel(relation) }}</small></span></button></div><el-empty v-else description="暂无关联知识" :image-size="64" /></section>

          <section v-if="record.bom" class="detail-section"><div class="section-head"><div><h2>标准BOM</h2><p>引用真实产品与主型号，价格按权限展示。</p></div><el-button v-if="canManage" :icon="Edit" @click="emit('editBom')">编辑BOM</el-button></div><el-table v-if="record.bom.items?.length" :data="record.bom.items" border><el-table-column prop="product" label="产品" min-width="170"/><el-table-column prop="modelCode" label="型号" min-width="120"/><el-table-column prop="quantity" label="数量" width="70"/><el-table-column prop="unit" label="单位" width="70"/><el-table-column prop="purpose" label="用途" min-width="130"/><el-table-column label="要求" width="90"><template #default="scope">{{ ({REQUIRED:'必选',RECOMMENDED:'推荐',OPTIONAL:'可选'} as any)[scope.row.requirementLevel] }}</template></el-table-column><el-table-column v-if="showPrice" label="小计" min-width="120"><template #default="scope">{{ scope.row.subtotal==null?'-':scope.row.currency+' '+Number(scope.row.subtotal).toLocaleString() }}</template></el-table-column></el-table><el-empty v-else description="暂无标准BOM" :image-size="64"/><div v-if="showPrice&&record.bom.total!=null" class="bom-total">参考总价 <strong>{{ record.bom.currency }} {{ Number(record.bom.total).toLocaleString() }}</strong></div></section>

          <section v-if="showPrice" class="detail-section"><div class="section-head"><div><h2>价格信息</h2><p>价格随知识对象展示，并受价格查看权限保护。</p></div></div><slot name="price"><el-empty description="暂无价格信息" :image-size="64" /></slot></section>
        </main>
        <aside class="detail-aside"><h3>维护信息</h3><dl><div><dt>数据状态</dt><dd>已确认</dd></div><div><dt>维护角色</dt><dd>{{ canManage ? '产品经理' : '只读用户' }}</dd></div><div><dt>记录编号</dt><dd>#{{ record.id }}</dd></div></dl></aside>
      </div>
    </template>
  </section>
</template>

