de dl{margin:14px 0 0}.detail-aside dl div{display:flex;justify-content:space-between;gap:16px;padding:11px 0;border-bottom:1px solid #edf1f5;font-size:13px}.detail-aside dt{color:#7b899b}.detail-aside dd{margin:0;color:#273950}.metric-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.metric-list div{display:grid;gap:4px;padding:12px;background:#f5f9ff;border-radius:6px}.metric-list span{font-size:12px;color:#748397}.metric-list strong{color:#173257}.boundary-list{margin:14px 0 0;padding-left:20px;color:#52637b;line-height:1.8}@media(max-width:1000px){.detail-layout{grid-template-columns:1fr}.detail-aside{order:-1}.detail-aside dl{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.detail-aside dl div{display:grid;gap:4px;border:0}}@media(max-width:700px){.detail-hero-v3{grid-template-columns:auto 1fr}.hero-actions{grid-column:1/-1}.relation-list,.metric-list{grid-template-columns:1fr}.detail-aside dl{grid-template-columns:1fr}.detail-section{padding:16px}}
